 Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){TextButton(onBack){Icon(Icons.Filled.ArrowBack,null);Text("بازگشت به فهرست پلاک‌ها")};Text(vehicle.title,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Text("پلاک ${vehicle.plate}",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Text("نوع: ${vehicle.vehicleType}");Text("مالک: $ownerName");Text("تعداد جرائم: ${Digits.toPersian(fines.size.toString())}");Text("جمع مبلغ جرائم: ${Money.format(totalFine,unit)}",color=Color(0xFFD33B45),fontWeight=FontWeight.Bold)}};Text("جرائم و پیامک‌های این پلاک",style=MaterialTheme.typography.titleMedium);if(vehicleMessages.isEmpty())Text("هنوز پیامکی برای این پلاک ثبت نشده است.");vehicleMessages.sortedByDescending{it.receivedAt}.forEach{m->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(4.dp)){Text(PersianDate.formatDateTime(m.receivedAt),style=MaterialTheme.typography.labelMedium);Text(m.body);if(!m.read)TextButton({scope.launch{dao.updateMessage(m.copy(read=true,vehicleId=vehicle.id))}}){Text("خواندم")}}}};Text("سوابق سرویس",style=MaterialTheme.typography.titleMedium);if(vehicleServices.isEmpty())Text("هنوز سابقه سرویسی ثبت نشده است.");vehicleServices.forEach{s->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("تاریخ: ${PersianDate.fromMillis(s.servicedAt).format()}");Text("کیلومتر: ${Digits.toPersian(s.currentKm.toString())}");if(s.oilType.isNotBlank())Text("روغن: ${s.oilType}");if(s.note.isNotBlank())Text(s.note)}}}}
}

