@Composable private fun IranianPlateInput(value:String,onValueChange:(String)->Unit){
 val parsed=remember(value){ir.kharjyar.app.core.sms.IranianPlateMatcher.extract(value)}
 var left by remember(value){mutableStateOf(parsed?.leftTwo.orEmpty())};var letter by remember(value){mutableStateOf(parsed?.letter.orEmpty())};var serial by remember(value){mutableStateOf(parsed?.serialThree.orEmpty())};var iran by remember(value){mutableStateOf(parsed?.iranCode.orEmpty())}
 fun emit(l:String=left,ch:String=letter,s:String=serial,i:String=iran){left=l;letter=ch;serial=s;iran=i;onValueChange("$l$ch${s}ایران$i")}
 val fieldColors=OutlinedTextFieldDefaults.colors(focusedTextColor=Color.Black,unfocusedTextColor=Color.Black,focusedContainerColor=Color.White,unfocusedContainerColor=Color.White,cursorColor=Color.Black,focusedBorderColor=Color(0xFF17458A),unfocusedBorderColor=Color(0xFF777777))
 Column(verticalArrangement=Arrangement.spacedBy(6.dp)){Text("شماره پلاک ایران",style=MaterialTheme.typography.labelLarge);CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr){Card(shape=RoundedCornerShape(10.dp),modifier=Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=Color(0xFFF4F4F4))){Row(Modifier.fillMaxWidth().padding(6.dp),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(4.dp)){Box(Modifier.width(26.dp).height(58.dp).background(Color(0xFF17458A),RoundedCornerShape(5.dp)),contentAlignment=Alignment.Center){Text("IR",color=Color.White,style=MaterialTheme.typography.labelSmall)};OutlinedTextField(left,{emit(l=Digits.normalize(it).filter(Char::isDigit).take(2))},placeholder={Text("۸۶",color=Color.Gray)},singleLine=true,textStyle=LocalTextStyle.current.copy(color=Color.Black),colors=fieldColors,modifier=Modifier.width(58.dp).height(58.dp));OutlinedTextField(letter,{raw->emit(ch=raw.filter{it in 'آ'..'ی'||it=='♿'}.take(1))},placeholder={Text("س",color=Color.Gray)},singleLine=true,textStyle=LocalTextStyle.current.copy(color=Color.Black),colors=fieldColors,modifier=Modifier.width(49.dp).height(58.dp));OutlinedTextField(serial,{emit(s=Digits.normalize(it).filter(Char::isDigit).take(3))},placeholder={Text("۶۷۳",color=Color.Gray)},singleLine=true,textStyle=LocalTextStyle.current.copy(color=Color.Black),colors=fieldColors,modifier=Modifier.width(76.dp).height(58.dp));OutlinedTextField(iran,{emit(i=Digits.normalize(it).filter(Char::isDigit).take(2))},label={Text("ایران",color=Color.Black)},placeholder={Text("۷۳",color=Color.Gray)},singleLine=true,textStyle=LocalTextStyle.current.copy(color=Color.Black),colors=fieldColors,modifier=Modifier.width(76.dp).height(58.dp))}}};Row(verticalAlignment=Alignment.CenterVertically){Text("برای پلاک ویژه: ",style=MaterialTheme.typography.bodySmall);TextButton({emit(ch="♿")}){Text("نماد معلولین ♿")};if(letter=="♿")TextButton({emit(ch="")}){Text("حرف معمولی")}}}
}

